import{_ as a,o,c as t,a2 as r}from"./chunks/framework.DHtetOlu.js";const u=JSON.parse('{"title":"Resolução","description":"","frontmatter":{},"headers":[],"relativePath":"guide/solver.md","filePath":"guide/solver.md"}'),s={name:"guide/solver.md"};function n(i,e,d,c,m,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="resolucao" tabindex="-1">Resolução <a class="header-anchor" href="#resolucao" aria-label="Permalink to &quot;Resolução&quot;">​</a></h1><p>Em <strong>Método de resolução</strong> fica a física do problema. O nó <strong>Campo magnético</strong> é criado junto com o projeto; o <code>+</code> ao lado de <strong>Modelo</strong> cria outras físicas, como um <strong>circuito externo</strong>. O ▶ resolve (gerando a malha antes, se precisar), e mensagens explicam o que falta: região sem material, falta de um contorno com A prescrito, curva B-H inválida…</p><h2 id="tipos-de-analise" tabindex="-1">Tipos de análise <a class="header-anchor" href="#tipos-de-analise" aria-label="Permalink to &quot;Tipos de análise&quot;">​</a></h2><p>Nas propriedades da física, escolha a <strong>análise</strong>:</p><table tabindex="0"><thead><tr><th>Análise</th><th>O que resolve</th><th>Parâmetros</th></tr></thead><tbody><tr><td>Magnetostática</td><td>campo de correntes contínuas e ímãs</td><td>—</td></tr><tr><td>Harmônica (AC)</td><td>regime senoidal permanente, com fasores</td><td>frequência (Hz)</td></tr><tr><td>Transitória</td><td>evolução no tempo, com correntes parasitas</td><td>passo Δt e tempo final</td></tr></tbody></table><h3 id="magnetostatica" tabindex="-1">Magnetostática <a class="header-anchor" href="#magnetostatica" aria-label="Permalink to &quot;Magnetostática&quot;">​</a></h3><p>Resolve −∇·(ν∇A) = J (mais o termo dos ímãs) com A_z no plano ou ψ = r·A_φ no axissimétrico. Se algum material tem curva B-H, o problema é <strong>não linear</strong> e resolvido por <strong>Newton-Raphson</strong> com busca linear; o número de iterações aparece nos resultados.</p><h3 id="harmonica-ac" tabindex="-1">Harmônica (AC) <a class="header-anchor" href="#harmonica-ac" aria-label="Permalink to &quot;Harmônica (AC)&quot;">​</a></h3><p>As correntes são <strong>amplitudes de pico</strong> na frequência dada. Condutores com σ &gt; 0 e sem fonte têm <strong>correntes parasitas</strong>. Materiais com curva B-H usam a permeabilidade efetiva (como no FEMM), iterada até convergir. Os resultados podem ser vistos ao longo de um período, A(t) = Re(Â e^{jωt}), e as integrais de superfície dão as <strong>perdas por correntes parasitas</strong> e as <strong>perdas no ferro</strong> (Steinmetz, com os coeficientes do material).</p><h3 id="transitoria" tabindex="-1">Transitória <a class="header-anchor" href="#transitoria" aria-label="Permalink to &quot;Transitória&quot;">​</a></h3><p>Euler implícito com passo Δt até o tempo final. As correntes podem ser <strong>funções de t</strong>, por exemplo <code>10*sin(2*pi*60*t)</code> ou <code>5*min(1, t/0.002)</code> (rampa de 2 ms até 5 A); condutores sem fonte têm correntes parasitas; o aço é não linear a cada passo. Nos resultados, a vista ganha uma <strong>barra de tempo</strong> e os itens das tabelas viram <strong>curvas no tempo</strong>.</p><h2 id="circuito-externo" tabindex="-1">Circuito externo <a class="header-anchor" href="#circuito-externo" aria-label="Permalink to &quot;Circuito externo&quot;">​</a></h2><p>Com a física <strong>Circuito</strong>, bobinas do modelo entram num esquemático com fontes, resistores, indutores e capacitores, resolvidos <strong>junto com o campo</strong> (acoplamento forte). Veja <a href="./circuit.html">Circuito externo</a>.</p><h2 id="desempenho" tabindex="-1">Desempenho <a class="header-anchor" href="#desempenho" aria-label="Permalink to &quot;Desempenho&quot;">​</a></h2><p>O solver roda num Web Worker, em WebAssembly, sem travar a interface. Problemas com dezenas de milhares de elementos resolvem em segundos na magnetostática linear. A matriz é esparsa, resolvida por LDLᵀ (estático) ou LU (AC e circuito). Veja a <a href="./../theory/formulation.html">formulação</a> para os detalhes.</p>',15)])])}const h=a(s,[["render",n]]);export{u as __pageData,h as default};
